import { createRuntimeManifest } from './runtimeManifest.js';

createRuntimeManifest({
  config: {
    appId: 'demo',
  },
});

calls.callExpression:
createRuntimeApiOperationExecutor({
      fetch: (url) => {
        calls.push(url);
        throw new Error('Internal API phase-1 execution must not reach fetch.');
      },
    })

(async () => {
      const result = await resolveRuntimeRepeatItemsAsync(repeat, {
        apis: effectiveConfig.apis,
        context: effectiveConfig.bindingContext,
        dataBindings: effectiveConfig.dataBindings,
        executeOperation: effectiveConfig.executeOperation,
        node,
        operationResults: effectiveConfig.operationResults,
        stateAdapter: effectiveConfig.stateAdapter,
        writeOperationResult: effectiveConfig.writeOperationResult,
      });

      if (repeatRequestIdRef.current !== requestId) {
        return;
      }

      setAsyncRepeatResult({ ...result, requestToken: repeatRequestToken });
    })

(async () => {
    const operationResults: Record<string, BindingValue | undefined> = {};

    for (const preparedLoader of args.plan.loaders) {
      const selection = resolveRuntimeBindingOperationSelection(
        preparedLoader.loader.operation,
        args.apis,
        diagnostics,
      );
      if (selection === undefined) {
        continue;
      }

      const result = await executeOperation({
        api: selection.api,
        endpoint: selection.endpoint,
        input: preparedLoader.input,
        node: args.screen.root,
        operation: preparedLoader.loader.operation,
      });
      diagnostics.push(...(result.diagnostics ?? []));

      if (!result.ok) {
        continue;
      }

      operationResults[preparedLoader.operationKey] = result.data;
    }

    return {
      dependencyKey: args.plan.requestKey,
      diagnostics,
      operationResults,
    };
  })

(async () => {
      const result = await executePreparedRuntimeScreenOperationLoaders({
        apis,
        executeOperation,
        plan,
        screen,
      });

      setState((currentState) => {
        const completion = completeRuntimeScreenOperationLoaderRequest({
          lifecycle: lifecycleRef.current,
          requestId,
          result,
          state: currentState.dependencyKey === requestKey ? currentState : request.state,
        });

        return completion.accepted ? completion.state : currentState;
      });
    })
